<?php
namespace App\Console\Commands;use App\Enums\UserRole;use App\Models\Person;use App\Models\RoleAssignment;use App\Models\User;use Illuminate\Console\Command;use Illuminate\Support\Str;
class GrantSystemAdmin extends Command{protected $signature='minutes:grant-admin {employee_no}';protected $description='Grant system administrator role';public function handle():int{$p=Person::where('employee_no',$this->argument('employee_no'))->first();if(!$p){$this->error('未找到已同步人员。');return self::FAILURE;}$u=User::firstOrCreate(['cas_account'=>$p->employee_no],['person_id'=>$p->id,'name'=>$p->name,'email'=>$p->email?:$p->employee_no.'@invalid.local','password'=>bcrypt(Str::random(64)),'is_active'=>true]);RoleAssignment::firstOrCreate(['user_id'=>$u->id,'role'=>UserRole::SystemAdmin->value,'organization_id'=>null]);$this->info('系统管理员授权成功。');return self::SUCCESS;}}
